#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int64 solve(int64 a, int64 b)
{
    if (a == 0) return b * b;
    if (b == 0) return a * a;
    return 3 * (2 * a + 2 * b - 2) + solve(a - 1, b - 1);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    while (n--)
    {
        int64 a, b;
        cin >> a >> b;
        cout << solve(a, b) << '\n';
    }

    return 0;
}

